const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const get = (j, key) => { const k = Object.keys(j).find(x => norm(x) === key); return k ? String(j[k] ?? '').trim() : ''; };

// on garde le chat_id Telegram déjà enregistré
let chatId = '';
for (const i of $('Lire profil actuel').all()) if (get(i.json, 'cle') === 'chat_id') chatId = get(i.json, 'valeur');

const f = $('On form submission').first().json;

// Langues : on regroupe les paires « Langue n°X » + « Niveau langue n°X » en une seule ligne
const langues = [];
for (let n = 1; n <= 5; n++) {
  const l = String(f['Langue n°' + n] ?? '').trim();
  const niv = String(f['Niveau langue n°' + n] ?? '').trim();
  if (!l || l.startsWith('—') || l.startsWith('Autre')) continue;
  langues.push(l + (niv && !niv.startsWith('—') ? ' (' + niv + ')' : ''));
}
const autreLangue = String(f['Autre langue'] ?? '').trim();
if (autreLangue) langues.push(autreLangue);

const ignorer = ['submittedAt', 'formMode', 'Autre langue'];
const lignes = [];
for (const [cle, v] of Object.entries(f)) {
  if (ignorer.includes(cle) || !cle.trim()) continue;
  if (cle.startsWith('Langue n°') || cle.startsWith('Niveau langue n°')) continue;
  const valeur = Array.isArray(v) ? v.join(', ') : String(v ?? '').trim();
  if (!valeur || valeur.startsWith('—')) continue;   // champs vides ou « — Aucun — »
  lignes.push({ json: { cle: cle.trim(), valeur } });
}
if (langues.length) lignes.push({ json: { cle: 'Langues', valeur: langues.join(', ') } });
lignes.push({ json: { cle: 'Profil mis à jour le', valeur: new Date().toISOString().slice(0, 10) } });
if (chatId) lignes.push({ json: { cle: 'chat_id', valeur: chatId } });
return lignes;
